#include <juce_audio_utils/juce_audio_utils.h>
#include <iostream>
using namespace juce;
class VstClock:public AudioPlayHead{public:double beat=0;bool running=true;Optional<PositionInfo>getPosition()const override{PositionInfo p;p.setBpm(120);p.setPpqPosition(beat);p.setIsPlaying(running);p.setTimeSignature(TimeSignature{4,4});p.setTimeInSamples((int64)(beat*24000));return p;}};
int main(int argc,char**argv){ScopedJuceInitialiser_GUI init;if(argc!=2)return 1;AudioPluginFormatManager formats;formats.addFormat(std::make_unique<VST3PluginFormat>());OwnedArray<PluginDescription> types;formats.getFormat(0)->findAllTypesForFile(types,argv[1]);if(types.isEmpty()){std::cerr<<"No VST3 class\n";return 2;}String error;auto plugin=formats.createPluginInstance(*types[0],48000,512,error);if(!plugin){std::cerr<<error<<"\n";return 3;}if(!plugin->producesMidi()){std::cerr<<"No MIDI output bus\n";return 4;}VstClock clock;plugin->setPlayHead(&clock);plugin->prepareToPlay(48000,512);AudioBuffer<float> audio(2,512);MidiBuffer midi;std::array<bool,128> active{};int on=0,off=0;
for(int i=0;i<1800;i++){midi.clear();plugin->processBlock(audio,midi);for(auto e:midi){auto m=e.getMessage();if(m.isNoteOn()){if(active[m.getNoteNumber()])return 5;active[m.getNoteNumber()]=true;on++;}else if(m.isNoteOff()){if(!active[m.getNoteNumber()])return 6;active[m.getNoteNumber()]=false;off++;}}clock.beat+=512./24000.;}
clock.running=false;midi.clear();plugin->processBlock(audio,midi);for(auto e:midi)if(e.getMessage().isNoteOff())off++;plugin->releaseResources();if(on==0||on!=off){std::cerr<<"MIDI mismatch "<<on<<" / "<<off<<"\n";return 7;}std::cout<<"PASS actual VST3 binary loaded: "<<on<<" paired MIDI notes through event output bus, host sync and stop.\n";}
